588: func decisionObsoleteReason(ctx context.Context, tx *writeTx, decision Decision) (string, error) {
589: 	if decision.Kind != "merge_ready" && decision.Kind != "recovery" && decision.Kind != "worker_exited" && decision.Kind != "pr_closed" && decision.Kind != "orphan" && decision.Kind != "review_cap" && decision.Kind != "quota" && decision.Kind != "budget" && decision.Kind != "dependency" {
590: 		return "", nil
591: 	}
592: 	var state State
593: 	var launches int
594: 	if err := tx.QueryRowContext(ctx, `SELECT state,launches FROM tasks WHERE id=? AND project_id=?`, decision.TaskID, decision.ProjectID).Scan(&state, &launches); err != nil {
595: 		return "", err
596: 	}
597: 	if decision.Kind == "merge_ready" {
598: 		var ready bool
599: 		if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM tasks t WHERE t.id=? AND t.state IN ('done','merging') AND (t.landing_mode<>'pr' OR EXISTS(SELECT 1 FROM pr_observations p WHERE p.task_id=t.id AND p.pr_url=t.pr_url AND p.id=(SELECT MAX(id) FROM pr_observations WHERE task_id=t.id AND pr_url=t.pr_url) AND p.state='OPEN' AND p.head_sha=t.gated_sha AND json_extract(p.checks,'$.state')='SUCCESS' AND p.review NOT IN ('CHANGES_REQUESTED','REVIEW_REQUIRED') AND p.mergeable='MERGEABLE')))`, decision.TaskID).Scan(&ready); err != nil {
600: 			return "", err
601: 		}
602: 		if state != StateDone && state != StateMerging {
603: 			return "Task left merge-ready state", nil
604: 		}
605: 		if !ready {
606: 			return "PR is no longer ready to merge", nil
607: 		}
608: 	}
609: 	if decision.Kind == "recovery" && (state != StateFailed && state != StateLost || launches != decision.TaskLaunches) {
610: 		return "Task no longer failed or lost", nil
611: 	}
612: 	if decision.Kind == "dependency" {
613: 		parts := strings.Split(decision.Origin, ":")
614: 		if len(parts) < 4 || parts[0] != "dependency" {
615: 			return "", nil
616: 		}
617: 		predecessorSeq := mustTaskSequence(parts[2])
618: 		var predecessorState State
619: 		if err := tx.QueryRowContext(ctx, `SELECT state FROM tasks WHERE project_id=? AND seq=?`, decision.ProjectID, predecessorSeq).Scan(&predecessorState); err != nil {
