40: func (s *Service) holdQueuedDependants(ctx context.Context, db *store.DB, project store.Project, predecessor store.Task) ([]string, error) {
41: 	dependants, err := queuedTaskDependants(ctx, db, project.ID, predecessor)
42: 	if err != nil || len(dependants) == 0 {
43: 		return nil, err
44: 	}
45: 	ids := make([]string, 0, len(dependants))
46: 	for _, dependant := range dependants {
47: 		dependentRef := taskIDString(dependant.Seq)
48: 		ids = append(ids, dependentRef)
49: 		if err := db.ObsoleteDependencyDecision(ctx, dependant.ID, dependentRef, taskIDString(predecessor.Seq)); err != nil {
50: 			return nil, err
51: 		}
52: 	}
53: 	origin := "teardown-dependants:" + taskIDString(predecessor.Seq) + ":" + strings.Join(ids, ",")
54: 	_, err = db.RaiseDecision(ctx, store.DecisionRequest{
55: 		ProjectID: project.ID,
56: 		TaskID:    predecessor.ID,
57: 		Origin:    origin,
58: 		Kind:      "teardown_dependants",
59: 		Question:  fmt.Sprintf("Tearing down %s left queued dependants %s. Re-point them to a replacement Task, or cascade their teardown?", taskIDString(predecessor.Seq), strings.Join(ids, ", ")),
60: 		Options:   []string{"re-point", "cascade"},
61: 	})
62: 	return ids, err
63: }
