65: func teardownDecisionDependants(ctx context.Context, db *store.DB, project store.Project, decision store.Decision) (store.Task, []store.Task, error) {
66: 	predecessor, err := db.TaskByID(ctx, project.ID, decision.TaskID)
67: 	if err != nil {
68: 		return store.Task{}, nil, err
69: 	}
70: 	parts := strings.Split(decision.Origin, ":")
71: 	if len(parts) != 3 || parts[0] != "teardown-dependants" || parts[1] != taskIDString(predecessor.Seq) {
72: 		return store.Task{}, nil, fmt.Errorf("teardown dependant Decision binding is invalid")
73: 	}
74: 	dependants := make([]store.Task, 0)
75: 	for _, taskRef := range strings.Split(parts[2], ",") {
76: 		dependant, err := db.Task(ctx, project.ID, taskRef)
77: 		if err != nil {
78: 			return store.Task{}, nil, fmt.Errorf("queued dependant %s no longer exists", taskRef)
79: 		}
80: 		if dependant.State != store.StateQueued {
81: 			continue
82: 		}
83: 		plan, err := dependant.AdmittedPlan()
84: 		if err != nil {
85: 			return store.Task{}, nil, admittedPlanFailure(err)
86: 		}
87: 		if plan == nil {
88: 			continue
89: 		}
90: 		for _, dependency := range plan.Dependencies {
91: 			if dependency.TaskID == taskIDString(predecessor.Seq) {
92: 				dependants = append(dependants, dependant)
93: 				break
94: 			}
95: 		}
96: 	}
97: 	return predecessor, dependants, nil
98: }
