97: func (db *DB) ReviseTaskPlans(ctx context.Context, revisions []TaskPlanRevision) error {
98: 	if len(revisions) == 0 {
99: 		return nil
100: 	}
101: 	type preparedRevision struct {
102: 		Task     Task
103: 		Previous taskplan.Plan
104: 		Plan     taskplan.Plan
105: 		Data     string
106: 		Repo     *TaskRepo
107: 	}
108: 	prepared := make([]preparedRevision, 0, len(revisions))
109: 	for _, revision := range revisions {
110: 		previous, err := revision.Task.AdmittedPlan()
111: 		if err != nil {
112: 			return err
113: 		}
114: 		if previous == nil || revision.Plan.Revision != previous.Revision+1 || revision.Plan.PreviousSHA256 != previous.SHA256() {
115: 			return fmt.Errorf("execution plan revision does not extend the admitted plan")
116: 		}
117: 		plan := revision.Plan
118: 		plan.AdmittedSHA256 = ""
119: 		data, err := plan.Encode()
120: 		if err != nil {
121: 			return err
122: 		}
123: 		data, err = db.externalizePlanJSON(data)
124: 		if err != nil {
125: 			return err
126: 		}
127: 		prepared = append(prepared, preparedRevision{Task: revision.Task, Previous: *previous, Plan: plan, Data: data, Repo: revision.Repo})
128: 	}
129: 	tx, err := db.beginTxWithRetry(ctx)
130: 	if err != nil {
131: 		return err
132: 	}
133: 	defer tx.Rollback()
134: 	for _, revision := range prepared {
135: 		task, plan, data := revision.Task, revision.Plan, revision.Data
136: 		result, err := tx.ExecContext(ctx, `UPDATE tasks SET plan_json=?, profile=?, dispatch_rule=?, workflow_run_id=?, plan_revision=?, gated_sha=CASE WHEN state='merging' THEN gated_sha ELSE '' END, updated_at=? WHERE id=? AND plan_json=? AND launches=? AND state=?`,
137: 			data, plan.Launch.ProfileName, plan.Launch.DispatchRule, storedWorkflowRunID(data), storedPlanRevision(data), time.Now().UnixMilli(), task.ID, task.PlanJSON, task.Launches, task.State)
138: 		if err != nil {
139: 			return err
140: 		}
141: 		if count, err := result.RowsAffected(); err != nil {
142: 			return err
143: 		} else if count != 1 {
144: 			return ErrStateRace
145: 		}
146: 		if _, err := tx.ExecContext(ctx, `INSERT INTO task_plan_revisions(task_id,revision,plan_json) VALUES(?,?,?)`, task.ID, plan.Revision, data); err != nil {
147: 			return err
148: 		}
149: 		if _, err := tx.ExecContext(ctx, `UPDATE task_repos SET gated_sha='' WHERE task_id=? AND EXISTS(SELECT 1 FROM tasks WHERE id=? AND state<>'merging')`, task.ID, task.ID); err != nil {
150: 			return err
151: 		}
152: 		if revision.Repo != nil {
153: 			repo := revision.Repo
154: 			if _, err := tx.ExecContext(ctx, `INSERT INTO task_repos(task_id,repo,worktree_path,base_ref,target_branch,landing_mode,state,updated_at) VALUES(?,?,?,?,?,?,'open',?)`, task.ID, repo.Repo, repo.WorktreePath, repo.BaseRef, repo.TargetBranch, repo.MergeMode, time.Now().UnixMilli()); err != nil {
155: 				return err
156: 			}
157: 		}
158: 		changedFields := plan.ChangedFields(revision.Previous)
159: 		reviewRelevant := false
160: 		for _, field := range changedFields {
161: 			switch field {
162: 			case "review", "validation_loops", "inputs", "execution", "preferences", "grants", "user_choice", "member_admissions":
163: 				reviewRelevant = true
164: 			}
165: 		}
166: 		invalidateReview := reviewRelevant && task.State != StateMerging
167: 		if invalidateReview {
168: 			if _, err := tx.ExecContext(ctx, `UPDATE validation_candidates SET state='stale',observed_author_sha=submitted_sha,updated_at=? WHERE task_id=? AND state IN ('preparing','active')`, time.Now().UnixMilli(), task.ID); err != nil {
169: 				return err
170: 			}
171: 			if _, err := tx.ExecContext(ctx, `UPDATE validation_stage_results SET invalidated_from_status=status,status='invalidated',invalidated_by_sha=(SELECT candidate_sha FROM validation_candidates WHERE id=validation_stage_results.candidate_id) WHERE task_id=? AND status IN ('passed','failed')`, task.ID); err != nil {
172: 				return err
173: 			}
174: 			if _, err := tx.ExecContext(ctx, `INSERT OR IGNORE INTO branch_author_invalidated_verdicts(task_id,change_task_id,invalidated_at) SELECT v.task_id,t.reviews_task_id,? FROM review_verdicts v JOIN tasks t ON t.id=v.task_id WHERE t.reviews_task_id=?`, time.Now().UnixMilli(), task.ID); err != nil {
175: 				return err
176: 			}
177: 			if _, err := tx.ExecContext(ctx, `UPDATE review_rounds SET status='void',verdict=NULL WHERE ship_task_id=? AND status IN ('admitted','verdict')`, task.ID); err != nil {
178: 				return err
179: 			}
180: 		}
181: 		note := fmt.Sprintf("Execution plan revised from %d to %d; changed fields: %s; prior revision evidence invalidated", revision.Previous.Revision, plan.Revision, strings.Join(changedFields, ", "))
182: 		if invalidateReview {
183: 			note += "; Review evidence invalidated because review-relevant fields changed"
184: 		}
185: 		if task.State == StateMerging {
186: 			note = fmt.Sprintf("Execution plan revised from %d to %d; changed fields: %s; merge gate retained", revision.Previous.Revision, plan.Revision, strings.Join(changedFields, ", "))
187: 		}
188: 		if _, err := tx.ExecContext(ctx, `INSERT INTO transitions(task_id,from_state,to_state,source,note,at) VALUES(?,?,?,?,?,?)`, task.ID, task.State, task.State, "lead", note, time.Now().UnixMilli()); err != nil {
189: 			return err
190: 		}
191: 	}
192: 	if err := tx.Commit(); err != nil {
193: 		return err
194: 	}
195: 	for _, revision := range prepared {
196: 		if err := db.PersistTask(ctx, revision.Task.ID); err != nil {
197: 			return err
198: 		}
199: 	}
200: 	return nil
201: }
